-- Aggiunto sconto combinato
ALTER TABLE `co_righe_promemoria` CHANGE `tipo_sconto` `tipo_sconto` ENUM('UNT','PRC','PRC+') NOT NULL DEFAULT 'UNT';
ALTER TABLE `co_righe_promemoria` ADD `sconto_percentuale_combinato` VARCHAR(255) NULL AFTER `sconto_percentuale`;

-- Corretta vista da Anagrafica delle sedi rimosse
UPDATE `zz_modules` 
SET `options` = 'SELECT\r\n    |select|\r\nFROM\r\n    `an_anagrafiche`\r\n    LEFT JOIN `an_relazioni` ON `an_anagrafiche`.`id_relazione` = `an_relazioni`.`id`\r\n    LEFT JOIN `an_relazioni_lang` ON (`an_relazioni_lang`.`id_record` = `an_relazioni`.`id` AND `an_relazioni_lang`.|lang|)\r\n    LEFT JOIN `an_tipi_anagrafiche_anagrafiche` ON `an_tipi_anagrafiche_anagrafiche`.`id_anagrafica` = `an_anagrafiche`.`id`\r\n    LEFT JOIN `an_tipi_anagrafiche` ON `an_tipi_anagrafiche`.`id` = `an_tipi_anagrafiche_anagrafiche`.`id_tipo_anagrafica`\r\n    LEFT JOIN `an_tipi_anagrafiche_lang` ON (`an_tipi_anagrafiche_lang`.`id_record` = `an_tipi_anagrafiche`.`id` AND `an_tipi_anagrafiche_lang`.|lang|)\r\n    LEFT JOIN (SELECT `id_anagrafica`, GROUP_CONCAT(`nome_sede` SEPARATOR \', \') AS nomi FROM `an_sedi` WHERE `deleted_at` IS NULL GROUP BY `id_anagrafica`) AS sedi ON `an_anagrafiche`.`id` = `sedi`.`id_anagrafica`\r\n    LEFT JOIN (SELECT `id_anagrafica`, GROUP_CONCAT(`nome` SEPARATOR \', \') AS nomi FROM `an_referenti` GROUP BY `id_anagrafica`) AS referenti ON `an_anagrafiche`.`id` = `referenti`.`id_anagrafica`\r\n    LEFT JOIN (\r\n        SELECT `co_pagamenti`.`id`, `co_pagamenti_lang`.`title` AS `nome`\r\n        FROM `co_pagamenti`\r\n        LEFT JOIN `co_pagamenti_lang` ON (`co_pagamenti_lang`.`id_record` = `co_pagamenti`.`id` AND `co_pagamenti_lang`.|lang|)\r\n    ) AS pagvendita ON `an_anagrafiche`.`id_pagamento_vendite` = `pagvendita`.`id`\r\n    LEFT JOIN (\r\n        SELECT `co_pagamenti`.`id`, `co_pagamenti_lang`.`title` AS `nome`\r\n        FROM `co_pagamenti`\r\n        LEFT JOIN `co_pagamenti_lang` ON (`co_pagamenti_lang`.`id_record` = `co_pagamenti`.`id` AND `co_pagamenti_lang`.|lang|)\r\n    ) AS pagacquisto ON `an_anagrafiche`.`id_pagamento_acquisti` = `pagacquisto`.`id`\r\n    LEFT JOIN `an_zone` ON `an_anagrafiche`.`id_zona` = `an_zone`.`id`\r\nWHERE\r\n    1=1\r\n    AND `an_anagrafiche`.`deleted_at` IS NULL\r\nGROUP BY\r\n    `an_anagrafiche`.`id`, `pagvendita`.`nome`, `pagacquisto`.`nome`\r\nHAVING\r\n    2=2\r\nORDER BY\r\n    `ragione_sociale`' WHERE `zz_modules`.`name` = 'Anagrafiche';